/* @autogenerated */
import { Injectable, Injector, inject } from '@angular/core';
import { HttpClient, HttpRequest } from '@angular/common/http';
import { OAuthService } from 'angular-oauth2-oidc';
import { filter } from 'rxjs';

const PENDING_KEY = 'stepup.pending';
const STATE_MARK = 'stepup';

@Injectable({ providedIn: 'root' })
export class StepUpService {
  private readonly oauth = inject(OAuthService);
  private readonly injector = inject(Injector);

  listen(): void {
    this.oauth.events.pipe(filter((e) => e.type === 'token_received')).subscribe(() => this.resumeIfPending());
  }

  start(req: HttpRequest<unknown>, acr?: string, maxAge?: string): void {
    sessionStorage.setItem(
      PENDING_KEY,
      JSON.stringify({
        method: req.method,
        url: req.urlWithParams,
        body: req.body,
      }),
    );
    const params: Record<string, string> = {};
    if (acr) params['acr_values'] = acr;
    if (maxAge) params['max_age'] = maxAge;
    this.oauth.initCodeFlow(STATE_MARK, params);
  }

  private resumeIfPending(): void {
    const raw = sessionStorage.getItem(PENDING_KEY);
    sessionStorage.removeItem(PENDING_KEY);
    if (this.oauth.state !== STATE_MARK || !raw) return;
    const p = JSON.parse(raw);
    // Perezoso: evita el ciclo HttpClient → interceptores → este servicio
    this.injector.get(HttpClient).request(p.method, p.url, { body: p.body }).subscribe();
  }
}
